void dtls_clear_queues(SSL *s) {
    /* Clear unprocessed records queue */
    while (!sk_RECORD_PENDING_num(s->unprocessed_records)) {
        RECORD_PENDING *pending = sk_RECORD_PENDING_pop(s->unprocessed_records);
        if (pending != NULL) {
            if (pending->record_data != NULL)
                OPENSSL_free(pending->record_data);
            OPENSSL_free(pending);
        }
    }

    /* Clear processed records queue */
    while (!sk_RECORD_processed_num(s->processed_records)) {
        RECORD_processed *processed = sk_RECORD_processed_pop(s->processed_records);
        if (processed != NULL) {
            if (processed->record_data != NULL)
                OPENSSL_free(processed->record_data);
            OPENSSL_free(processed);
        }
    }

    /* Clear buffered messages queue */
    while (!sk_BUFFERED_MSG_num(s->buffered_messages)) {
        BUFFERED_MSG *msg = sk_BUFFERED_MSG_pop(s->buffered_messages);
        if (msg != NULL) {
            if (msg->msg_data != NULL)
                OPENSSL_free(msg->msg_data);
            OPENSSL_free(msg);
        }
    }

    /* Clear sent messages queue */
    while (!sk_SENT_MSG_num(s->sent_messages)) {
        SENT_MSG *msg = sk_SENT_MSG_pop(s->sent_messages);
        if (msg != NULL) {
            if (msg->msg_data != NULL)
                OPENSSL_free(msg->msg_data);
            OPENSSL_free(msg);
        }
    }

    /* Clear buffered application data queue */
    while (!sk_APP_DATA_num(s->buffered_app_data)) {
        APP_DATA *data = sk_APP_DATA_pop(s->buffered_app_data);
        if (data != NULL) {
            if (data->app_data != NULL)
                OPENSSL_free(data->app_data);
            OPENSSL_free(data);
        }
    }
}

void clear_dtls_queues(SSL *s) {
    SSL3_RECORD *rec;
    int i;

    /* Clear unprocessed records */
    while (s->s3->rrec_pool) {
        rec = sk_SSL3_RECORD_pop(s->s3->rrec_pool);
        if (rec->data) {
            OPENSSL_free(rec->data);
        }
        OPENSSL_free(rec);
    }

    /* Clear processed records */
    while (s->s3->wrec_pool) {
        rec = sk_SSL3_RECORD_pop(s->s3->wrec_pool);
        if (rec->data) {
            OPENSSL_free(rec->data);
        }
        OPENSSL_free(rec);
    }

    /* Clear buffered messages */
    while (s->s3->rbuf.buf) {
        if (s->s3->rbuf.buf->data) {
            OPENSSL_free(s->s3->rbuf.buf->data);
        }
        OPENSSL_free(s->s3->rbuf.buf);
        s->s3->rbuf.buf = NULL;
    }

    /* Clear sent messages */
    for (i = 0; i < s->s3->send_buffer_num; i++) {
        if (s->s3->send_buffer[i].data) {
            OPENSSL_free(s->s3->send_buffer[i].data);
        }
    }
    OPENSSL_free(s->s3->send_buffer);
    s->s3->send_buffer = NULL;
    s->s3->send_buffer_num = 0;

    /* Clear buffered application data */
    for (i = 0; i < s->s3->rbuf_num; i++) {
        if (s->s3->rbuf.buf[i].data) {
            OPENSSL_free(s->s3->rbuf.buf[i].data);
        }
    }
    OPENSSL_free(s->s3->rbuf.buf);
    s->s3->rbuf.buf = NULL;
    s->s3->rbuf_num = 0;
}

void clear_dtls_queues(SSL *s) {
    /* Clear unprocessed records queue */
    while (s->unprocessed_records.head != NULL) {
        SSL3_RECORD *r = s->unprocessed_records.head;
        s->unprocessed_records.head = r->next;
        if (r->data != NULL)
            OPENSSL_free(r->data);
        OPENSSL_free(r);
    }
    s->unprocessed_records.tail = NULL;
    s->unprocessed_records.num_records = 0;

    /* Clear processed records queue */
    while (s->processed_records != NULL) {
        SSL3_RECORD *r = s->processed_records;
        s->processed_records = r->next;
        if (r->data != NULL)
            OPENSSL_free(r->data);
        OPENSSL_free(r);
    }

    /* Clear buffered messages queue */
    while (s->rbuf.buffer != NULL) {
        WPACKET *pkt = s->rbuf.buffer;
        s->rbuf.buffer = NULL;
        WPACKET_cleanup(pkt);
        OPENSSL_free(pkt);
    }

    /* Clear sent messages queue */
    while (s->sbuf.buffer != NULL) {
        WPACKET *pkt = s->sbuf.buffer;
        s->sbuf.buffer = NULL;
        WPACKET_cleanup(pkt);
        OPENSSL_free(pkt);
    }

    /* Clear buffered application data */
    if (s->s3->rbuf.app_data_len > 0) {
        OPENSSL_free(s->s3->rbuf.app_data);
        s->s3->rbuf.app_data = NULL;
        s->s3->rbuf.app_data_len = 0;
    }
}

void dtls_clear_queues(SSL *s) {
    /* Clear unprocessed records queue */
    while (s->d1->unprocessed_rcds) {
        DTLS1_RECORD *r = s->d1->unprocessed_rcds;
        s->d1->unprocessed_rcds = r->next;
        if (r->rbuf.buf)
            OPENSSL_free(r->rbuf.buf);
        OPENSSL_free(r);
    }

    /* Clear processed records queue */
    while (s->d1->processed_rcds) {
        DTLS1_RECORD *r = s->d1->processed_rcds;
        s->d1->processed_rcds = r->next;
        if (r->rbuf.buf)
            OPENSSL_free(r->rbuf.buf);
        OPENSSL_free(r);
    }

    /* Clear buffered messages queue */
    while (s->d1->buffered_messages) {
        DTLS1_BUFFERED_MESSAGE *bm = s->d1->buffered_messages;
        s->d1->buffered_messages = bm->next;
        if (bm->msg)
            OPENSSL_free(bm->msg);
        OPENSSL_free(bm);
    }

    /* Clear sent messages queue */
    while (s->d1->sent_messages) {
        SENT_MSG *sm = s->d1->sent_messages;
        s->d1->sent_messages = sm->next;
        OPENSSL_free(sm);
    }

    /* Clear buffered application data */
    while (s->d1->buffered_app_data) {
        BUF_ALLOC *ba = s->d1->buffered_app_data;
        s->d1->buffered_app_data = ba->next;
        if (ba->data)
            OPENSSL_free(ba->data);
        OPENSSL_free(ba);
    }

    s->d1->next_handshake_seq = 0;
}
